export const GLOBAL_CHALLENGES_ACTIVITIES = [
// PHASE A — FONDASI (1-20)
{n:1,type:"mcq",micro:"Masalah bersama",q:"'Masalah bersama umat manusia' adalah tantangan yang...",options:["memengaruhi banyak negara & orang di seluruh dunia, sehingga butuh perhatian & kerja sama bersama","tidak nyata & hanya dibesar-besarkan","hanya dialami satu negara & tidak memengaruhi yang lain"],answer:0,explain:"Kemiskinan, penyakit, akses air bersih, & perubahan iklim adalah contoh tantangan yang melintasi batas negara.",hint:"Melintasi batas negara, butuh kerja sama."},
{n:2,type:"mcq",micro:"Contoh masalah bersama",q:"Contoh masalah yang dihadapi banyak negara di dunia:",options:["jumlah hari libur nasional","akses air bersih, pendidikan yang belum merata, & penyakit menular","warna bendera negara"],answer:1,explain:"Ini beberapa contoh tantangan yang dialami dalam berbagai tingkat oleh banyak negara, bukan hanya satu tempat.",hint:"Air bersih, pendidikan, kesehatan."},
{n:3,type:"tf",micro:"Kemajuan juga terjadi",q:"Benar atau Salah: Selain tantangan, dunia juga sudah mencapai banyak kemajuan, seperti berkurangnya jumlah orang yang hidup dalam kemiskinan ekstrem dibanding beberapa dekade lalu.",answer:true,explain:"Penting melihat gambaran seimbang: ada tantangan besar, & juga ada kemajuan nyata hasil kerja keras banyak pihak.",hint:"Ada tantangan, ada juga kemajuan."},
{n:4,type:"mcq",micro:"Air bersih",q:"Mengapa akses air bersih & sanitasi dianggap tantangan global?",options:["karena air tidak penting bagi kesehatan","karena airnya mahal untuk semua orang","karena tidak semua orang di dunia punya akses mudah ke air minum yang aman & fasilitas sanitasi yang layak"],answer:2,explain:"Banyak komunitas masih berjuang mendapatkan air bersih setiap hari, yang berdampak besar pada kesehatan & pendidikan.",hint:"Tidak semua orang punya akses mudah."},
{n:5,type:"mcq",micro:"Pendidikan sebagai tantangan global",q:"Salah satu alasan pendidikan dianggap tantangan bersama dunia:",options:["masih ada jutaan anak di berbagai negara yang belum bisa bersekolah karena jarak, biaya, atau situasi darurat","sekolah tidak penting untuk masa depan","semua anak di dunia sudah bersekolah dengan sempurna"],answer:0,explain:"Pendidikan yang merata membuka peluang besar bagi individu & negara, sehingga kesenjangannya menjadi perhatian dunia.",hint:"Masih banyak anak belum bersekolah."},
{n:6,type:"tf",micro:"Kesehatan global",q:"Benar atau Salah: Penyakit menular yang muncul di satu wilayah dunia tidak mungkin memengaruhi negara lain mana pun.",answer:false,explain:"Sebaliknya, penyakit menular berpotensi menyebar lewat perjalanan & perdagangan, sehingga negara-negara saling berbagi informasi kesehatan & bekerja sama mendeteksi wabah sejak dini.",hint:"Penyakit bisa menyebar lintas negara."},
{n:7,type:"mcq",micro:"Iklim sebagai isu bersama",q:"Perubahan iklim disebut isu global karena...",options:["hanya terjadi di satu benua","gas rumah kaca dari mana pun di dunia memengaruhi iklim seluruh planet, sehingga dampaknya dirasakan di banyak tempat","cuaca selalu sama sepanjang tahun"],answer:1,explain:"Atmosfer bumi adalah satu sistem yang menyelimuti semua negara, sehingga perubahan di satu tempat berdampak luas.",hint:"Satu atmosfer untuk seluruh planet."},
{n:8,type:"mcq",micro:"Kerja sama internasional",q:"Untuk mengatasi masalah bersama seperti ini, negara-negara biasanya...",options:["saling menyalahkan tanpa bertindak","bekerja sendiri-sendiri tanpa berkomunikasi","berbagi ilmu, sumber daya, & menyepakati langkah bersama lewat organisasi & perjanjian internasional"],answer:2,explain:"Kerja sama internasional (mis. lewat PBB & organisasi kesehatan dunia) adalah cara utama menangani masalah lintas batas.",hint:"Berbagi ilmu & menyepakati langkah bersama."},
{n:9,type:"tf",micro:"Bukan hanya tugas negara kaya",q:"Benar atau Salah: Mengatasi masalah global sepenuhnya tanggung jawab satu atau dua negara tertentu saja, & negara lain tidak punya peran apa pun.",answer:false,explain:"Sebaliknya, mengatasi masalah global adalah tanggung jawab semua negara sesuai kemampuannya masing-masing — negara dengan sumber daya lebih besar sering diharapkan berkontribusi lebih banyak, tetapi semua tetap punya peran.",hint:"Semua ikut berperan sesuai kemampuan."},
{n:10,type:"mcq",micro:"Tujuan Pembangunan Berkelanjutan",q:"Banyak negara di dunia sepakat pada seperangkat tujuan bersama (di antaranya mengurangi kemiskinan, menyediakan pendidikan berkualitas, & menjaga lingkungan) untuk dicapai bertahap. Ini dikenal sebagai...",options:["Tujuan Pembangunan Berkelanjutan (TPB), sebuah kesepakatan global","aturan satu negara saja","sekadar slogan tanpa rencana"],answer:0,explain:"TPB (dikenal juga dengan singkatan bahasa Inggrisnya, SDGs) adalah 17 tujuan yang disepakati negara-negara dunia sebagai peta jalan bersama hingga tahun 2030.",hint:"Kesepakatan bersama banyak negara, punya nama resmi."},
{n:11,type:"open",micro:"Masalah global yang kamu tahu",q:"Sebutkan satu masalah global yang pernah kamu dengar atau baca, & jelaskan singkat mengapa itu memengaruhi lebih dari satu negara.",sample:"Aku pernah membaca tentang sampah plastik di laut. Ini masalah global karena arus laut membawa sampah dari satu negara ke pantai negara lain, & sampah plastik yang terurai jadi partikel kecil bisa ditemukan di laut mana pun, tidak hanya di tempat sampah itu awalnya dibuang.",explain:"Menghubungkan masalah dengan alasan mengapa ia bersifat lintas negara memperdalam pemahaman literasi global.",hint:"1 masalah + alasan ia melintasi batas negara."},
{n:12,type:"mcq",micro:"Kemiskinan sebagai isu global",q:"Kemiskinan dianggap masalah bersama karena...",options:["hanya terjadi pada orang malas","ada jutaan orang di berbagai negara yang kesulitan memenuhi kebutuhan dasar meski sudah bekerja keras, karena berbagai faktor struktural","kemiskinan tidak memengaruhi siapa pun selain orang itu sendiri"],answer:1,explain:"Kemiskinan sering disebabkan faktor yang lebih besar dari pilihan individu, seperti akses pendidikan, kesehatan, & peluang kerja yang tidak merata.",hint:"Bukan sekadar soal 'malas atau rajin'."},
{n:13,type:"mcq",micro:"Bencana alam & kerja sama",q:"Saat bencana alam besar terjadi di suatu negara, negara-negara lain sering...",options:["menutup semua hubungan dengan negara itu","mengabaikannya sepenuhnya","mengirim bantuan kemanusiaan (makanan, obat, tim penyelamat) sebagai bentuk solidaritas global"],answer:2,explain:"Bantuan bencana lintas negara adalah salah satu bentuk paling nyata dari solidaritas global.",hint:"Solidaritas lewat bantuan kemanusiaan."},
{n:14,type:"tf",micro:"Membicarakan tanpa menakuti",q:"Benar atau Salah: Kita bisa membicarakan & belajar tentang masalah global secara jujur & serius tanpa harus merasa putus asa atau sangat ketakutan.",answer:true,explain:"Memahami masalah dengan tenang & fokus pada solusi lebih membantu daripada tenggelam dalam rasa takut.",hint:"Serius & jujur, tanpa perlu panik."},
{n:15,type:"open",micro:"Kemajuan yang menggembirakan",q:"Cari atau ingat satu contoh kemajuan/keberhasilan dunia dalam mengatasi masalah bersama (kesehatan, pendidikan, lingkungan). Tuliskan singkat.",sample:"Aku pernah membaca bahwa penyakit cacar berhasil diberantas sepenuhnya dari dunia lewat program vaksinasi internasional yang bekerja sama selama bertahun-tahun. Ini menunjukkan bahwa kerja sama global yang gigih bisa benar-benar menyelesaikan masalah besar.",explain:"Mengingat kemajuan nyata membantu kita percaya bahwa usaha bersama bisa membuahkan hasil.",hint:"1 contoh keberhasilan dunia yang nyata."},
{n:16,type:"mcq",micro:"Peran organisasi internasional",q:"Organisasi seperti PBB & badan-badan kesehatan/pendidikan dunia berperan untuk...",options:["menjadi wadah negara-negara berkoordinasi, berbagi data, & menyepakati langkah bersama menghadapi masalah global","tidak memiliki peran apa pun","memerintah semua negara secara langsung"],answer:0,explain:"Organisasi internasional membantu negara-negara bekerja sama tanpa menghilangkan kedaulatan masing-masing negara.",hint:"Wadah koordinasi, bukan pemerintah dunia."},
{n:17,type:"order",micro:"Dari masalah ke aksi bersama",q:"Urutkan langkah umum dunia menangani masalah bersama:",items:["Ilmuwan & lembaga mengumpulkan data tentang masalahnya","Negara-negara & organisasi mendiskusikan & menyepakati langkah bersama","Sumber daya (dana, tenaga ahli, teknologi) dikerahkan untuk menjalankan rencana","Kemajuan dipantau & rencana disesuaikan bila perlu"],answer:[0,1,2,3],explain:"Data → kesepakatan → aksi → pemantauan adalah pola umum penanganan masalah global.",hint:"Kumpulkan data dulu, pantau di akhir."},
{n:18,type:"mcq",micro:"Setiap orang punya peran",q:"Individu biasa (termasuk pelajar) bisa ikut berperan dalam masalah global dengan cara...",options:["tidak ada peran sama sekali untuk individu","kebiasaan sehari-hari yang bertanggung jawab, belajar & menyebarkan informasi yang benar, & mendukung aksi kolektif di lingkungannya","hanya menunggu pemerintah bertindak"],answer:1,explain:"Perubahan besar sering dimulai dari banyak tindakan kecil yang tersebar luas.",hint:"Kebiasaan kecil + belajar + dukung aksi bersama."},
{n:19,type:"tf",micro:"Tidak satu penyebab tunggal",q:"Benar atau Salah: Masalah global seperti kemiskinan atau perubahan iklim biasanya punya banyak sebab yang saling terkait, bukan satu penyebab tunggal yang sederhana.",answer:true,explain:"Memahami banyak sebab yang saling terkait membantu kita mencari solusi yang lebih tepat, bukan solusi yang terlalu menyederhanakan.",hint:"Banyak sebab yang saling terkait."},
{n:20,type:"mcq",micro:"Ringkasan Fondasi",q:"Inti memahami masalah bersama umat manusia:",options:["dunia hanya penuh masalah tanpa harapan","masalah global bukan urusan siapa-siapa","ada tantangan besar yang melintasi batas negara (kesehatan, pendidikan, lingkungan, kemiskinan), yang butuh kerja sama banyak pihak & tetap diimbangi dengan melihat kemajuan yang sudah dicapai"],answer:2,explain:"Sikap yang sehat adalah serius menghadapi tantangan sambil tetap melihat kemajuan & peran yang bisa kita ambil.",hint:"Tantangan lintas batas + kerja sama + tetap ada harapan."},
// PHASE B — PEMAHAMAN (21-40)
{n:21,type:"classify",micro:"Skala masalah",q:"Kelompokkan setiap masalah menurut skalanya:",items:["Perubahan iklim global","Meja kelasmu yang goyang","Akses air bersih di berbagai negara","Buku catatanmu yang hilang"],groups:["Masalah global/lintas negara","Masalah pribadi/lokal kecil"],answer:{"Masalah global/lintas negara":["Perubahan iklim global","Akses air bersih di berbagai negara"],"Masalah pribadi/lokal kecil":["Meja kelasmu yang goyang","Buku catatanmu yang hilang"]},explain:"Membedakan skala masalah membantu kita tahu jenis solusi & pihak yang perlu terlibat.",hint:"Melibatkan banyak negara vs urusan pribadimu."},
{n:22,type:"mcq",micro:"TPB / SDGs sebagai peta jalan",q:"Tujuan Pembangunan Berkelanjutan mencakup berbagai bidang seperti mengurangi kemiskinan, kesehatan, pendidikan, kesetaraan, & lingkungan. Gunanya sebagai...",options:["peta jalan & target bersama yang membantu negara-negara mengukur kemajuan & mengarahkan usaha mereka","peraturan yang memaksa satu negara tertentu saja","daftar keinginan tanpa rencana"],answer:0,explain:"TPB memberi kerangka & target terukur (misalnya tenggat tahun) agar usaha banyak pihak bisa diarahkan & dinilai kemajuannya.",hint:"Peta jalan & target terukur bersama."},
{n:23,type:"mcq",micro:"Ketimpangan akses",q:"Salah satu tantangan global adalah ketimpangan: sebagian orang punya akses mudah ke layanan penting (kesehatan, listrik, internet), sementara yang lain tidak. Ini penting diperhatikan karena...",options:["ketimpangan tidak berpengaruh pada apa pun","memperbesar jarak kesempatan hidup antarorang & antarnegara, yang bisa menghambat kemajuan bersama","semua orang memang seharusnya berbeda-beda tanpa alasan"],answer:1,explain:"Mengurangi ketimpangan akses adalah salah satu cara memberi lebih banyak orang kesempatan yang adil untuk berkembang.",hint:"Ketimpangan memperbesar jarak kesempatan hidup."},
{n:24,type:"mcq",micro:"Konflik & pengungsian",q:"Konflik bersenjata di suatu wilayah bisa memaksa banyak orang mengungsi ke negara lain. Ini menjadi perhatian global karena...",options:["pengungsi selalu menjadi masalah bagi negara tujuan","tidak ada yang perlu dipedulikan","menyangkut keselamatan & martabat manusia, serta membutuhkan kerja sama negara-negara untuk membantu & melindungi para pengungsi"],answer:2,explain:"Perlindungan pengungsi adalah salah satu bentuk tanggung jawab kemanusiaan bersama yang diatur lewat kerja sama internasional.",hint:"Soal keselamatan & martabat manusia."},
{n:25,type:"tf",micro:"Solusi butuh banyak pihak",q:"Benar atau Salah: Masalah sebesar kemiskinan global atau perubahan iklim biasanya membutuhkan kerja sama pemerintah, perusahaan, ilmuwan, & masyarakat biasa sekaligus, bukan hanya satu pihak saja.",answer:true,explain:"Masalah besar & rumit jarang terselesaikan oleh satu jenis pihak saja; dibutuhkan kolaborasi lintas sektor.",hint:"Butuh banyak jenis pihak sekaligus."},
{n:26,type:"mcq",micro:"Ketahanan pangan",q:"'Ketahanan pangan' berarti...",options:["kemampuan semua orang mendapatkan makanan yang cukup & bergizi secara stabil, tidak hanya sesekali","hanya soal menyimpan stok beras","kemampuan makanan bertahan lama tanpa basi"],answer:0,explain:"Ketahanan pangan mencakup ketersediaan, akses, & keberlanjutan pasokan makanan bagi semua orang.",hint:"Semua orang, cukup & bergizi, stabil."},
{n:27,type:"mcq",micro:"Perubahan iklim & pertanian",q:"Perubahan pola cuaca akibat perubahan iklim bisa memengaruhi pertanian dengan cara...",options:["selalu membuat semua panen lebih baik","membuat musim tanam & panen menjadi kurang bisa diprediksi, yang bisa mengganggu ketahanan pangan di beberapa wilayah","tidak berpengaruh sama sekali pada pertanian"],answer:1,explain:"Petani mengandalkan pola musim yang bisa diprediksi; perubahan pola cuaca membuat perencanaan pertanian lebih sulit.",hint:"Musim jadi kurang bisa diprediksi."},
{n:28,type:"open",micro:"Menghubungkan dua masalah",q:"Pilih dua masalah global yang menurutmu saling berkaitan (mis. pendidikan & kemiskinan, atau iklim & ketahanan pangan). Jelaskan keterkaitannya.",sample:"Pendidikan & kemiskinan saling berkaitan: anak dari keluarga miskin sering kesulitan mengakses pendidikan berkualitas karena biaya atau harus membantu bekerja, sehingga peluang mereka keluar dari kemiskinan di masa depan jadi lebih kecil. Sebaliknya, pendidikan yang baik bisa membuka peluang pekerjaan yang lebih baik & membantu memutus siklus kemiskinan itu.",explain:"Masalah global jarang berdiri sendiri; melihat keterkaitannya membantu merancang solusi yang lebih menyeluruh.",hint:"2 masalah + bagaimana keduanya saling memengaruhi."},
{n:29,type:"mcq",micro:"Energi bersih",q:"Banyak negara berinvestasi pada energi bersih (matahari, angin, air) sebagai bagian dari mengatasi masalah global karena...",options:["tidak ada alasan tertentu","energi bersih selalu lebih mahal & tidak berguna","energi bersih membantu mengurangi emisi gas rumah kaca sambil tetap menyediakan listrik untuk kebutuhan yang terus tumbuh"],answer:2,explain:"Transisi energi bersih adalah salah satu langkah utama menangani perubahan iklim sambil menjaga pasokan energi.",hint:"Kurangi emisi + tetap penuhi kebutuhan energi."},
{n:30,type:"order",micro:"Kisah keberhasilan: pemberantasan penyakit",q:"Urutkan tahapan umum keberhasilan dunia memberantas suatu penyakit lewat vaksinasi:",items:["Ilmuwan mengembangkan & menguji vaksin yang aman & efektif","Negara-negara & organisasi kesehatan menyepakati program vaksinasi bersama","Vaksin didistribusikan secara luas, termasuk ke wilayah terpencil","Kasus penyakit dipantau hingga menurun drastis atau hilang"],answer:[0,1,2,3],explain:"Contoh nyata seperti pemberantasan cacar mengikuti pola ini: riset, kesepakatan, distribusi luas, & pemantauan hasil.",hint:"Kembangkan vaksin dulu, pantau hasil di akhir."},
{n:31,type:"mcq",micro:"Kesenjangan digital",q:"'Kesenjangan digital' merujuk pada...",options:["perbedaan akses ke internet & teknologi antara orang/wilayah yang satu dengan yang lain, yang bisa memperbesar kesenjangan peluang","kecepatan mengetik seseorang","perbedaan model ponsel yang dipakai orang"],answer:0,explain:"Wilayah yang minim akses internet bisa tertinggal dalam pendidikan & peluang ekonomi di era digital.",hint:"Perbedaan akses teknologi, bukan model gawai."},
{n:32,type:"tf",micro:"Bukan hanya masalah negara berkembang",q:"Benar atau Salah: Masalah seperti perubahan iklim, polusi, atau kesehatan mental hanya dialami negara berkembang & sama sekali tidak menyentuh negara maju.",answer:false,explain:"Sebaliknya, banyak tantangan global bersifat lintas tingkat kemakmuran & juga dialami negara maju, meski bentuk & tingkat keparahannya bisa berbeda.",hint:"Bukan eksklusif untuk satu jenis negara."},
{n:33,type:"mcq",micro:"Data sebagai dasar aksi",q:"Sebelum negara-negara menyepakati langkah menangani suatu masalah global, biasanya diperlukan...",options:["opini yang paling populer saja","data & penelitian yang menunjukkan besarnya masalah & penyebabnya","tebakan tanpa bukti"],answer:1,explain:"Kebijakan global yang baik didasarkan pada bukti & data, bukan sekadar opini atau kesan.",hint:"Data & penelitian jadi dasar."},
{n:34,type:"mcq",micro:"Bantuan yang memberdayakan",q:"Bantuan internasional yang paling efektif untuk masalah jangka panjang biasanya...",options:["tidak melibatkan masyarakat setempat sama sekali","hanya memberi barang sekali lalu selesai","membantu membangun kemampuan lokal (pelatihan, infrastruktur, alih pengetahuan) agar masyarakat bisa mandiri ke depannya"],answer:2,explain:"Bantuan yang memberdayakan menciptakan solusi yang bertahan lama, bukan ketergantungan terus-menerus.",hint:"Membangun kemampuan, bukan sekadar memberi sekali."},
{n:35,type:"mcq",micro:"Peran anak muda",q:"Beberapa gerakan global tentang lingkungan & keadilan sosial pernah dimulai atau digerakkan oleh...",options:["termasuk anak muda & pelajar yang bersuara & mengorganisir aksi tentang isu yang mereka pedulikan","tidak pernah ada peran anak muda","hanya orang dewasa & pejabat"],answer:0,explain:"Sejarah menunjukkan anak muda bisa menjadi penggerak perhatian dunia pada suatu isu, meski keputusan besar tetap melibatkan banyak pihak.",hint:"Anak muda juga bisa jadi penggerak."},
{n:36,type:"open",micro:"Aksi kecil untuk isu besar",q:"Pilih satu masalah global yang kamu pedulikan. Tuliskan satu tindakan kecil & realistis yang bisa kamu lakukan di lingkunganmu sendiri terkait isu itu.",sample:"Masalah: sampah plastik yang mencemari laut. Tindakan kecilku: membawa botol minum & kantong belanja sendiri agar mengurangi sampah plastik sekali pakai, serta mengajak keluarga memilah sampah plastik untuk didaur ulang di lingkungan rumah.",explain:"Menghubungkan isu besar dengan tindakan kecil yang bisa dijalankan membuat kepedulian menjadi nyata, bukan hanya wacana.",hint:"1 masalah global + 1 tindakan kecil realistis."},
{n:37,type:"mcq",micro:"Menyeimbangkan berita",q:"Berita tentang masalah global sering fokus pada hal buruk karena lebih menarik perhatian. Sikap pembaca yang seimbang:",options:["hanya percaya berita buruk & berhenti berharap","sadari kecenderungan ini, & sesekali cari juga laporan tentang kemajuan/solusi yang sudah dicapai","berhenti membaca berita sama sekali"],answer:1,explain:"Mencari gambaran yang seimbang (masalah & kemajuan) membantu kita tetap termotivasi bertindak, bukan putus asa.",hint:"Cari juga berita tentang kemajuan/solusi."},
{n:38,type:"tf",micro:"Setiap tindakan diperhitungkan",q:"Benar atau Salah: Karena masalah global sangat besar, tindakan satu sekolah atau satu komunitas kecil sama sekali tidak berarti apa-apa.",answer:false,explain:"Sebaliknya, banyak perubahan besar dimulai dari kumpulan tindakan kecil di banyak tempat yang menjumlah menjadi dampak besar.",hint:"Tindakan kecil bisa menjumlah jadi besar."},
{n:39,type:"mcq",micro:"Kesehatan mental sebagai isu global",q:"Kesehatan mental mulai diakui sebagai tantangan global karena...",options:["masalah ini hanya dialami segelintir orang di satu negara","tidak ada hubungannya dengan kesejahteraan seseorang","banyak orang di berbagai negara mengalami tekanan, kecemasan, atau kondisi kesehatan mental lain yang memengaruhi kualitas hidup & butuh dukungan yang layak"],answer:2,explain:"Kesadaran akan pentingnya kesehatan mental berkembang di banyak negara sebagai bagian dari kesejahteraan menyeluruh manusia.",hint:"Dialami banyak orang di banyak negara."},
{n:40,type:"mcq",micro:"Ringkasan Pemahaman",q:"Cara memahami masalah global secara sehat & seimbang:",options:["mengenali skala & keterkaitan antarmasalah, mendasarkan pemahaman pada data, & tetap melihat kemajuan yang sudah dicapai sambil mencari peran yang bisa diambil","hanya fokus pada berita buruk","menganggap masalah besar bukan urusan siapa pun"],answer:0,explain:"Pemahaman yang matang menggabungkan kejujuran tentang tantangan dengan harapan yang berdasar & keinginan untuk bertindak.",hint:"Skala + data + kemajuan + peran nyata."},
// PHASE C — PENERAPAN (41-60)
{n:41,type:"mcq",micro:"Terapan: proyek kelas tentang TPB",q:"Kelasmu memilih satu Tujuan Pembangunan Berkelanjutan untuk dipelajari & dibuat aksi kecil. Langkah awal yang baik:",options:["langsung membuat poster tanpa riset","pelajari data & fakta dasarnya dari sumber tepercaya, lalu diskusikan aksi apa yang relevan & bisa dilakukan di sekolah","meniru proyek sekolah lain tanpa memahami isinya"],answer:1,explain:"Aksi yang bermakna dimulai dari pemahaman yang benar tentang isunya.",hint:"Riset dulu, baru rancang aksi."},
{n:42,type:"mcq",micro:"Terapan: hemat air di sekolah",q:"Sekolahmu ingin ikut berkontribusi pada isu air bersih global dengan tindakan lokal. Tindakan yang relevan:",options:["mengabaikan isu ini karena sekolahnya punya air cukup","membiarkan keran menyala terus","mengecek & memperbaiki keran bocor, memasang poster hemat air, & mengedukasi murid tentang pentingnya air bersih"],answer:2,explain:"Meski sekolahmu punya cukup air, hemat air adalah kontribusi lokal terhadap kesadaran global tentang sumber daya yang terbatas.",hint:"Hemat & edukasi, meski airmu sendiri cukup."},
{n:43,type:"mcq",micro:"Terapan: memilah informasi bencana",q:"Kamu melihat kabar tentang bencana kelaparan di suatu wilayah, lengkap dengan angka yang mencengangkan tanpa sumber jelas. Sikap kritis:",options:["periksa sumbernya ke lembaga kemanusiaan resmi sebelum membagikan, agar informasi yang tersebar akurat","mengabaikannya karena tidak yakin","langsung membagikan karena terasa penting"],answer:0,explain:"Menyebarkan informasi yang akurat penting agar bantuan & perhatian diarahkan dengan tepat.",hint:"Cek sumber resmi sebelum membagikan."},
{n:44,type:"open",micro:"Terapan: memilih isu untuk proyek",q:"Dari isu-isu global (kemiskinan, pendidikan, kesehatan, air bersih, iklim, kesetaraan), pilih satu yang paling ingin kamu pelajari lebih dalam & jelaskan alasannya.",sample:"Aku memilih isu pendidikan, karena aku percaya pendidikan adalah kunci yang membuka banyak isu lain — anak yang berpendidikan lebih mungkin memahami kesehatan, mengelola uang dengan baik, & ikut menjaga lingkungan di masa depan. Aku juga penasaran bagaimana caranya membuat pendidikan berkualitas bisa dijangkau anak-anak di daerah yang sulit diakses.",explain:"Memilih isu berdasarkan alasan pribadi yang jelas membuat proses belajar lebih bermakna & bertahan lama.",hint:"1 isu + alasan pribadi memilihnya."},
{n:45,type:"mcq",micro:"Terapan: penggalangan dana yang bertanggung jawab",q:"Kelas ingin menggalang dana untuk membantu korban bencana di negara lain. Cara yang bertanggung jawab:",options:["mengumpulkan uang tunai tanpa pencatatan","menyalurkan lewat lembaga kemanusiaan resmi & tepercaya, serta mencatat & melaporkan penggunaannya secara terbuka","menyimpan sendiri sebagian dananya"],answer:1,explain:"Menyalurkan lewat lembaga resmi memastikan bantuan sampai ke yang membutuhkan dengan aman & efektif.",hint:"Lewat lembaga resmi + transparan."},
{n:46,type:"order",micro:"Terapan: kampanye kesadaran sekolah",q:"Urutkan langkah membuat kampanye kesadaran isu global sederhana di sekolah:",items:["Pilih satu isu & pelajari fakta dasarnya dari sumber tepercaya","Rancang pesan yang jelas, akurat, & tidak menakut-nakuti berlebihan","Buat media sederhana (poster, presentasi singkat) & sampaikan ke teman-teman","Ajak teman melakukan satu aksi kecil yang konkret terkait isu itu"],answer:[0,1,2,3],explain:"Pelajari dulu → rancang pesan yang bertanggung jawab → sampaikan → ajak aksi nyata.",hint:"Pelajari fakta dulu, ajak aksi di akhir."},
{n:47,type:"mcq",micro:"Terapan: menyikapi angka besar",q:"Kamu membaca 'jutaan orang terdampak masalah X'. Cara memahami angka besar seperti ini dengan bijak:",options:["menganggap angka besar pasti dilebih-lebihkan","mengabaikannya karena terlalu besar untuk dipahami","sadari di balik angka besar ada individu-individu nyata, & cari cerita atau konteks yang membuatnya lebih mudah dipahami"],answer:2,explain:"Angka besar bisa terasa abstrak; menghubungkannya dengan cerita individu membantu empati & pemahaman.",hint:"Di balik angka besar, ada individu nyata."},
{n:48,type:"tf",micro:"Terapan: konsumsi bertanggung jawab",q:"Benar atau Salah: Kebiasaan tidak boros makanan & energi di rumah terlalu remeh untuk dianggap sebagai kontribusi pada isu ketahanan pangan & energi global.",answer:false,explain:"Sebaliknya, kebiasaan sehari-hari yang bertanggung jawab, bila dilakukan banyak orang, ikut meringankan tekanan pada sumber daya bersama.",hint:"Kebiasaan kecil, kontribusi nyata."},
{n:49,type:"mcq",micro:"Terapan: menghormati martabat dalam kampanye",q:"Saat membuat materi kampanye tentang kemiskinan atau bencana, penting untuk...",options:["menyampaikan fakta dengan hormat pada martabat orang yang terdampak, tanpa mengeksploitasi penderitaan mereka untuk efek dramatis","tidak perlu memikirkan perasaan orang yang terdampak","menampilkan foto orang yang menderita seburuk mungkin agar dramatis"],answer:0,explain:"Kampanye yang etis menginformasikan & menggerakkan tanpa merendahkan martabat orang yang digambarkan.",hint:"Fakta yang hormat, bukan eksploitasi penderitaan."},
{n:50,type:"mcq",micro:"Terapan: memilih sumber belajar isu global",q:"Untuk belajar tentang suatu isu global, sumber yang baik untuk dicari:",options:["hanya satu unggahan viral di media sosial","laporan resmi organisasi internasional, media tepercaya, & bila memungkinkan sumber dari orang yang mengalaminya langsung","gosip dari teman"],answer:1,explain:"Sumber yang kredibel & beragam memberi pemahaman yang lebih akurat & berimbang.",hint:"Sumber resmi + beragam + suara langsung bila bisa."},
{n:51,type:"mcq",micro:"Terapan: menyikapi ketidakadilan global",q:"Kamu belajar bahwa sebagian negara menyumbang emisi jauh lebih besar daripada negara lain, tetapi dampaknya dirasakan lebih berat oleh negara yang menyumbang sedikit. Sikap kritis:",options:["mengabaikan ketimpangan ini","menganggap ini adil-adil saja","kenali ini sebagai isu keadilan global yang nyata, & dukung solusi yang mempertimbangkan tanggung jawab & kemampuan tiap pihak"],answer:2,explain:"Memahami ketimpangan dampak & tanggung jawab adalah bagian penting dari literasi global yang matang.",hint:"Ini soal keadilan; tanggung jawab tak selalu merata."},
{n:52,type:"open",micro:"Terapan: surat harapan",q:"Tulis surat singkat (3-5 kalimat) yang ditujukan pada 'para pemimpin dunia' tentang satu isu global yang kamu pedulikan & harapanmu.",sample:"Kepada para pemimpin dunia, saya seorang pelajar yang peduli pada isu air bersih. Saya berharap lebih banyak negara mau berbagi teknologi & dana untuk membangun sumur & fasilitas air bersih di daerah yang kesulitan, karena air adalah kebutuhan dasar setiap anak untuk bisa sehat & bersekolah dengan baik. Saya percaya kerja sama yang tulus antarnegara bisa membuat perbedaan nyata bagi jutaan keluarga.",explain:"Menulis harapan dengan jelas melatih kemampuan menyuarakan kepedulian secara membangun.",hint:"3-5 kalimat, isu + harapan konkret."},
{n:53,type:"mcq",micro:"Terapan: menyikapi perdebatan kebijakan",q:"Dua kelompok berdebat tentang cara terbaik menangani suatu masalah global (mis. energi). Sikap warga dunia yang belajar:",options:["dengarkan kedua argumen, cari data pendukungnya, & pahami bahwa kebijakan yang kompleks sering punya trade-off (untung-rugi) yang perlu ditimbang","menganggap perdebatan ini tidak penting","langsung memihak salah satu tanpa memahami argumennya"],answer:0,explain:"Kebijakan global sering rumit dengan berbagai pertimbangan; memahami trade-off membantu penilaian yang lebih matang.",hint:"Dengar argumen, pahami untung-ruginya."},
{n:54,type:"tf",micro:"Terapan: menjaga motivasi",q:"Benar atau Salah: Merayakan kemajuan kecil (mis. berkurangnya sampah plastik sekolah dalam sebulan) bisa membantu menjaga semangat untuk terus berkontribusi pada isu yang lebih besar.",answer:true,explain:"Melihat hasil nyata, meski kecil, membantu kita percaya bahwa usaha kita berarti & mendorong untuk terus melangkah.",hint:"Rayakan kemajuan kecil untuk menjaga semangat."},
{n:55,type:"mcq",micro:"Terapan: proyek pertukaran solusi",q:"Kelasmu ingin belajar dari sekolah di negara lain tentang cara mereka menghemat energi. Manfaat kegiatan ini:",options:["tidak ada manfaatnya","bisa menemukan ide yang belum terpikirkan & menyesuaikannya dengan kondisi sekolahmu sendiri","hanya membuang waktu"],answer:1,explain:"Berbagi solusi lintas negara adalah salah satu cara nyata mempercepat kemajuan mengatasi masalah bersama.",hint:"Temukan ide baru, sesuaikan dengan kondisimu."},
{n:56,type:"order",micro:"Terapan: dari isu global ke aksi sekolah",q:"Urutkan proses mengubah kepedulian tentang isu global menjadi program sekolah nyata:",items:["Pilih isu global yang relevan dengan lingkungan sekolah","Pelajari & kumpulkan data tentang kondisi terkait isu itu di sekolahmu sendiri","Rancang program yang realistis sesuai sumber daya sekolah","Jalankan, evaluasi, & bagikan hasilnya ke sekolah lain bila memungkinkan"],answer:[0,1,2,3],explain:"Global ke lokal: pilih isu → data lokal → program realistis → jalankan & bagikan.",hint:"Pilih isu dulu, bagikan hasil di akhir."},
{n:57,type:"mcq",micro:"Terapan: menghadapi rasa kewalahan",q:"Kamu merasa kewalahan karena masalah global terasa terlalu besar untuk dihadapi seorang diri. Cara mengatasinya:",options:["mencoba menyelesaikan semua masalah sekaligus sendirian","berhenti peduli sama sekali","fokus pada satu isu & satu tindakan kecil yang bisa kamu mulai sekarang, & ingat bahwa kamu bagian dari usaha bersama banyak orang"],answer:2,explain:"Memilih fokus yang realistis mencegah rasa kewalahan & membuat kepedulian bertahan lama.",hint:"Fokus pada satu isu, satu langkah, ingat kamu tidak sendirian."},
{n:58,type:"mcq",micro:"Terapan: bertanya sebelum menyimpulkan",q:"Kamu mendengar klaim sederhana seperti 'negara miskin karena malas'. Pertanyaan kritis yang perlu diajukan:",options:["apa saja faktor sejarah, geografis, & struktural yang mungkin memengaruhi kondisi ekonomi suatu negara, selain soal usaha individu?","apakah orang yang bilang itu orang penting?","tidak perlu bertanya, langsung terima"],answer:0,explain:"Kemiskinan tingkat negara biasanya melibatkan banyak faktor kompleks, bukan sekadar 'malas atau rajin'.",hint:"Cari faktor sejarah & struktural, bukan cuma 'usaha individu'."},
{n:59,type:"tf",micro:"Terapan: menghubungkan pelajaran sekolah",q:"Benar atau Salah: Pelajaran sains, matematika, & bahasa yang kamu pelajari di sekolah tidak ada gunanya untuk memahami atau mengatasi masalah global.",answer:false,explain:"Sebaliknya, memahami data, sains lingkungan, & berkomunikasi lintas bahasa semuanya relevan & berguna untuk isu global.",hint:"Pelajaran sekolah terhubung ke isu dunia nyata."},
{n:60,type:"mcq",micro:"Ringkasan Penerapan",q:"Menerapkan kepedulian pada masalah global secara nyata berarti...",options:["menyerahkan semuanya pada pemerintah","memilih isu yang relevan, belajar dari sumber tepercaya, mengambil tindakan kecil yang realistis, & menjaga informasi yang disebarkan tetap akurat & hormat","hanya membicarakannya tanpa bertindak"],answer:1,explain:"Kepedulian yang matang menggabungkan pemahaman, tindakan nyata, & tanggung jawab dalam menyebarkan informasi.",hint:"Pilih isu, belajar, bertindak, akurat & hormat."},
// PHASE D — PENALARAN (61-80)
{n:61,type:"mcq",micro:"Trade-off dalam kebijakan global",q:"Membangun banyak pembangkit energi bersih butuh biaya besar & waktu, sementara kebutuhan energi mendesak sekarang. Ini contoh...",options:["tidak ada solusinya sama sekali","masalah yang tidak nyata","trade-off (pertukaran untung-rugi): manfaat jangka panjang vs biaya & tantangan jangka pendek yang perlu ditimbang bersama"],answer:2,explain:"Banyak kebijakan global melibatkan trade-off yang perlu ditimbang, bukan solusi sempurna tanpa biaya.",hint:"Manfaat jangka panjang vs biaya sekarang."},
{n:62,type:"mcq",micro:"Solusi yang terlalu sederhana",q:"Klaim 'cukup tanam satu pohon per orang & perubahan iklim selesai' berisiko karena...",options:["menyederhanakan masalah yang sebenarnya kompleks & butuh banyak langkah lain (energi bersih, kebijakan, perubahan industri), meski menanam pohon tetap bermanfaat","menanam pohon adalah solusi satu-satunya yang benar","menanam pohon tidak berguna sama sekali"],answer:0,explain:"Berhati-hati pada solusi 'ajaib' yang terlalu menyederhanakan masalah besar; banyak langkah biasanya diperlukan bersamaan.",hint:"Bermanfaat, tapi bukan solusi tunggal yang cukup."},
{n:63,type:"tf",micro:"Data perlu konteks",q:"Benar atau Salah: Angka tentang masalah global (mis. tingkat kemiskinan suatu negara) perlu dilihat bersama konteksnya (tren dari waktu ke waktu, cara pengukuran) agar tidak disalahpahami.",answer:true,explain:"Satu angka tanpa konteks bisa menyesatkan; melihat tren & metodenya memberi gambaran yang lebih akurat.",hint:"Angka butuh tren & metode untuk dipahami benar."},
{n:64,type:"mcq",micro:"Menimbang kepentingan berbeda",q:"Sebuah negara berkembang ingin membangun industri untuk mengentaskan kemiskinan, tetapi ini berpotensi menambah emisi. Ketegangan ini menunjukkan...",options:["negara berkembang tidak boleh berkembang sama sekali","kebutuhan mengentaskan kemiskinan & menjaga lingkungan bisa saling menantang, sehingga solusi yang adil perlu mempertimbangkan dukungan (dana, teknologi bersih) bagi negara yang sedang berkembang","emisi tidak menjadi masalah bagi negara berkembang"],answer:1,explain:"Keadilan global mempertimbangkan bahwa negara berkembang berhak atas kemajuan, sambil dunia bersama mencari jalan yang lebih bersih.",hint:"Dua kebutuhan sah yang perlu diselaraskan dengan dukungan."},
{n:65,type:"mcq",micro:"Solusi lokal yang tak selalu cocok di tempat lain",q:"Sebuah program yang berhasil mengatasi suatu masalah di satu negara belum tentu langsung berhasil bila diterapkan sama persis di negara lain, karena...",options:["semua negara benar-benar identik","program itu pasti gagal di mana pun","konteks budaya, ekonomi, & geografis yang berbeda bisa memengaruhi keberhasilan sebuah solusi, sehingga perlu penyesuaian"],answer:2,explain:"Solusi global yang baik sering perlu disesuaikan ('lokalisasi') agar cocok dengan konteks setempat.",hint:"Konteks berbeda perlu penyesuaian."},
{n:66,type:"open",micro:"Menimbang sebuah kebijakan",q:"Sebuah kota mempertimbangkan melarang kendaraan berbahan bakar tertentu demi mengurangi polusi, tetapi ini bisa menyulitkan orang yang belum mampu membeli kendaraan alternatif. Tuliskan pertimbangan untuk kedua sisi & satu usulan jalan tengah.",sample:"Sisi lingkungan: mengurangi kendaraan berpolusi tinggi penting untuk kualitas udara & kesehatan warga jangka panjang. Sisi ekonomi: banyak warga bergantung pada kendaraan yang mereka punya & belum mampu membeli yang baru. Usulan jalan tengah: menerapkan aturan secara bertahap dengan tenggat waktu yang jelas, disertai subsidi atau insentif bagi warga berpenghasilan rendah untuk beralih ke transportasi umum atau kendaraan yang lebih bersih.",explain:"Kebijakan global-lokal yang baik menimbang dampak lingkungan & dampak sosial-ekonomi sekaligus, mencari jalan tengah yang adil.",hint:"Sisi lingkungan + sisi ekonomi + jalan tengah."},
{n:67,type:"mcq",micro:"Menghindari doom-mongering",q:"Sebuah pesan berlebihan mengklaim 'dunia akan segera hancur total & tidak ada gunanya berusaha'. Sikap kritis:",options:["pesan yang sangat ekstrem seperti ini patut dipertanyakan; fakta ilmiah tentang tantangan global umumnya menekankan urgensi bertindak, bukan bahwa segalanya sudah tidak ada harapan","menyebarkannya karena terdengar penting","percaya sepenuhnya & berhenti berusaha"],answer:0,explain:"Pesan yang menakut-nakuti secara ekstrem justru bisa membuat orang putus asa & berhenti bertindak — kebalikan dari yang dibutuhkan.",hint:"Ekstrem & tanpa harapan = patut dicurigai."},
{n:68,type:"mcq",micro:"Kemajuan tidak berarti selesai",q:"Menyadari bahwa dunia sudah mencapai kemajuan pada suatu isu (mis. berkurangnya kemiskinan ekstrem) sebaiknya membuat kita...",options:["berhenti peduli karena sudah 'beres'","tetap termotivasi melanjutkan usaha, karena kemajuan menunjukkan hal itu MUNGKIN dicapai, bukan bahwa masalahnya sudah tuntas","menganggap semua data kemajuan itu bohong"],answer:1,explain:"Kemajuan adalah bukti bahwa usaha bersama bisa berhasil, sekaligus pengingat bahwa pekerjaan belum selesai sepenuhnya.",hint:"Bukti bahwa usaha berhasil, bukan tanda 'selesai'."},
{n:69,type:"tf",micro:"Perspektif ganda",q:"Benar atau Salah: Memahami masalah global dengan baik berarti kita harus memilih salah satu saja — mengakui keseriusan tantangannya, ATAU tetap punya harapan & bertindak, tidak bisa keduanya sekaligus.",answer:false,explain:"Sebaliknya, kedua hal itu bisa dipegang bersamaan — kadang disebut 'harapan yang realistis': jujur tentang tantangan, tanpa kehilangan motivasi untuk bertindak.",hint:"Serius pada tantangan + tetap ada harapan, sekaligus."},
{n:70,type:"order",micro:"Menilai klaim solusi ajaib",q:"Kamu membaca 'Teknologi X akan menyelesaikan seluruh krisis energi dunia dalam setahun'. Urutkan cara menilainya:",items:["Cari tahu apa sebenarnya teknologi X & sejauh mana ia sudah terbukti bekerja","Periksa siapa yang mengklaim & apakah ada kepentingan tertentu di baliknya","Bandingkan dengan pandangan ahli independen tentang teknologi tersebut","Simpulkan dengan hati-hati; solusi tunggal & instan untuk masalah kompleks jarang terjadi"],answer:[0,1,2,3],explain:"Klaim solusi ajaib untuk masalah kompleks pantas ditelusuri sumber, kepentingan, & pandangan ahli independennya.",hint:"Cari tahu teknologinya dulu, simpulkan hati-hati di akhir."},
{n:71,type:"mcq",micro:"Tanggung jawab & kemampuan",q:"Dalam kerja sama global, adil bila pembagian tanggung jawab mempertimbangkan...",options:["hanya negara kecil yang bertanggung jawab","semua pihak menanggung persis sama besar tanpa melihat kontribusi & kemampuannya","kontribusi historis pada masalah & kemampuan ekonomi/teknologi tiap pihak, sehingga yang lebih mampu & berkontribusi besar menanggung porsi lebih besar"],answer:2,explain:"Prinsip 'tanggung jawab yang berbeda namun bersama' sering dipakai dalam perjanjian & kesepakatan global.",hint:"Sesuai kontribusi & kemampuan, bukan rata sama besar."},
{n:72,type:"tf",micro:"Bukti mengalahkan opini populer",q:"Benar atau Salah: Bila bukti ilmiah yang kuat bertentangan dengan opini yang populer di media sosial tentang suatu isu global, bukti ilmiah yang kredibel sebaiknya lebih dipercaya.",answer:true,explain:"Popularitas sebuah opini tidak sama dengan kebenarannya; bukti yang diuji secara ilmiah & tepercaya tetap jadi rujukan utama.",hint:"Bukti kredibel > opini populer."},
{n:73,type:"mcq",micro:"Menyikapi ketidakpastian ilmiah",q:"Kadang ilmuwan belum sepenuhnya sepakat tentang detail sebuah isu (mis. seberapa cepat sebuah perubahan akan terjadi). Sikap yang matang:",options:["pahami bahwa sains bisa yakin pada arah besar suatu masalah sambil tetap menyempurnakan detail angkanya — ketidakpastian detail tidak menghapus kesimpulan besar yang didukung banyak bukti","tunggu sampai semua ilmuwan 100% sepakat pada segala hal sebelum bertindak","karena ada ketidakpastian, berarti masalahnya tidak nyata sama sekali"],answer:0,explain:"Ketidakpastian pada detail teknis berbeda dengan meragukan keseluruhan kesimpulan yang didukung banyak bukti independen.",hint:"Yakin pada arah besar, detail terus disempurnakan."},
{n:74,type:"open",micro:"Menimbang argumen berlawanan",q:"Cari (dari ingatanmu atau bacaan) satu argumen yang mendukung & satu yang menyoroti kekhawatiran tentang sebuah kebijakan global (mis. energi nuklir, pajak karbon, atau bantuan luar negeri). Tuliskan keduanya secara adil.",sample:"Topik: energi nuklir. Mendukung: energi nuklir bisa menghasilkan listrik besar dengan emisi karbon yang rendah, membantu mengurangi ketergantungan pada bahan bakar fosil. Kekhawatiran: risiko keamanan bila terjadi kecelakaan & tantangan mengelola limbah radioaktif dalam jangka sangat panjang. Menimbang keduanya penting sebelum menyimpulkan sikap tentang isu ini.",explain:"Menyajikan dua sisi argumen secara adil melatih kemampuan menilai kebijakan global yang kompleks tanpa bias sepihak.",hint:"1 argumen mendukung + 1 kekhawatiran, adil."},
{n:75,type:"mcq",micro:"Solidaritas tanpa menghakimi",q:"Saat membantu atau mempelajari masyarakat yang menghadapi masalah berat (kemiskinan, bencana), sikap yang hormat:",options:["menganggap mereka lemah & tidak berdaya","mengakui kekuatan, usaha, & kearifan mereka sendiri dalam menghadapi situasi, bukan hanya melihat mereka sebagai 'korban' semata","mengasihani secara berlebihan di depan mereka"],answer:1,explain:"Masyarakat yang menghadapi kesulitan tetap punya kekuatan & usaha sendiri; menghormati itu penting, bukan hanya melihat mereka sebagai objek belas kasihan.",hint:"Akui kekuatan & usaha mereka, bukan hanya 'korban'."},
{n:76,type:"tf",micro:"Bukan kompetisi antarisu",q:"Benar atau Salah: Peduli pada satu isu global (mis. lingkungan) berarti kita tidak boleh atau tidak bisa peduli pada isu lain (mis. pendidikan) pada saat yang sama.",answer:false,explain:"Sebaliknya, banyak isu global saling terkait & kita bisa peduli pada lebih dari satu, sesuai kemampuan & fokus kita.",hint:"Bukan pilih satu, bisa peduli beberapa."},
{n:77,type:"mcq",micro:"Menilai janji kebijakan",q:"Sebuah negara berjanji mencapai target lingkungan tertentu di masa depan. Cara menilai keseriusan janji itu:",options:["abaikan semua janji kebijakan","percaya begitu saja karena sudah dijanjikan","periksa langkah nyata & kemajuan yang sudah dilakukan sejauh ini menuju target itu, bukan hanya kata-kata"],answer:2,explain:"Janji yang baik dinilai dari tindakan & kemajuan terukur, bukan sekadar pernyataan.",hint:"Lihat tindakan nyata, bukan hanya kata-kata."},
{n:78,type:"mcq",micro:"Kompleksitas & kesabaran",q:"Masalah global besar biasanya tidak selesai dalam waktu singkat. Sikap yang realistis:",options:["memahami bahwa perubahan besar butuh waktu & usaha berkelanjutan, sambil tetap mendorong kemajuan bertahap","berhenti berharap karena terlalu lama","berharap semuanya selesai dalam setahun & kecewa bila tidak"],answer:0,explain:"Kesabaran yang aktif — terus mendorong kemajuan sambil realistis tentang waktu — lebih berkelanjutan daripada berharap solusi instan.",hint:"Butuh waktu & usaha berkelanjutan."},
{n:79,type:"tf",micro:"Kolaborasi lintas keahlian",q:"Benar atau Salah: Satu jenis keahlian saja (misalnya hanya ilmuwan, atau hanya pembuat kebijakan) biasanya sudah cukup untuk mengatasi masalah global yang kompleks.",answer:false,explain:"Sebaliknya, mengatasi masalah global sering membutuhkan kolaborasi antara ilmuwan, pembuat kebijakan, pelaku usaha, & masyarakat, karena tiap pihak punya peran & pengetahuan berbeda yang saling melengkapi.",hint:"Berbagai keahlian saling melengkapi."},
{n:80,type:"mcq",micro:"Ringkasan Penalaran",q:"Cara berpikir kritis & seimbang tentang masalah global:",options:["menganggap masalah global tidak punya jalan keluar sama sekali","memahami trade-off & kompleksitas, mendasarkan pendapat pada bukti, mewaspadai solusi ajaib & pesan yang berlebihan, & memegang harapan yang realistis","percaya semua klaim viral tentang isu global"],answer:1,explain:"Penalaran yang matang tentang isu global menghindari dua ekstrem: optimisme naif & keputusasaan berlebihan.",hint:"Trade-off + bukti + waspada solusi ajaib + harapan realistis."},
// PHASE E — TANTANGAN (81-100)
{n:81,type:"mcq",micro:"Analisis kebijakan multi-sisi",q:"Sebuah kesepakatan iklim internasional meminta negara maju membantu mendanai transisi energi bersih di negara berkembang. Alasan utama pendekatan ini:",options:["negara maju melakukan ini tanpa alasan tertentu","negara berkembang tidak mampu apa pun sendiri","negara maju umumnya berkontribusi lebih besar secara historis pada emisi & punya sumber daya lebih besar, sehingga membantu mempercepat solusi global yang adil"],answer:2,explain:"Ini mencerminkan prinsip tanggung jawab & kemampuan yang berbeda dalam kerja sama global.",hint:"Kontribusi historis + kemampuan lebih besar."},
{n:82,type:"open",micro:"Analisis isu menyeluruh",q:"Pilih satu isu global. Tuliskan: (a) mengapa ini masalah bersama (bukan hanya satu negara), (b) satu kemajuan yang sudah dicapai, (c) satu tantangan yang masih tersisa, (d) satu peran yang bisa diambil pelajar sepertimu.",sample:"Isu: akses pendidikan bagi anak perempuan di beberapa wilayah dunia. (a) Ini masalah bersama karena memengaruhi jutaan anak di berbagai negara & berkaitan dengan isu kemiskinan serta kesetaraan global. (b) Kemajuan: jumlah anak perempuan yang bersekolah meningkat signifikan di banyak wilayah dalam beberapa dekade terakhir berkat program & kesadaran bersama. (c) Tantangan: di beberapa daerah, jarak sekolah, biaya, & norma sosial tertentu masih menghalangi. (d) Peran pelajar: belajar tentang isu ini, mendukung penggalangan dana atau kampanye sekolah yang kredibel, & menghargai kesempatan pendidikan yang kumiliki sendiri.",explain:"Analisis menyeluruh menyeimbangkan pemahaman masalah, apresiasi kemajuan, kejujuran tentang tantangan, & peran nyata yang bisa diambil.",hint:"Mengapa bersama + kemajuan + tantangan + peranmu."},
{n:83,type:"mcq",micro:"Menimbang kritik terhadap bantuan internasional",q:"Beberapa orang mengkritik bahwa bantuan internasional kadang tidak efektif atau disalahgunakan. Sikap kritis yang seimbang:",options:["akui bahwa kritik ini penting untuk mendorong perbaikan (transparansi, akuntabilitas), sambil tetap menghargai bantuan yang terbukti efektif & mengubah hidup banyak orang","abaikan semua kritik karena bantuan pasti selalu baik","karena ada kritik, berarti semua bantuan internasional buruk & harus dihentikan"],answer:0,explain:"Kritik yang membangun mendorong perbaikan sistem bantuan, bukan alasan untuk berhenti peduli sepenuhnya.",hint:"Kritik untuk perbaikan, bukan alasan berhenti peduli."},
{n:84,type:"tf",micro:"Bukan sekadar amal, tapi juga keadilan",q:"Benar atau Salah: Membantu mengatasi masalah global murni soal kebaikan hati sukarela, & sama sekali tidak ada kaitannya dengan keadilan atau tanggung jawab atas penyebab masalah.",answer:false,explain:"Sebaliknya, sebagian orang memandangnya juga sebagai soal keadilan — terutama saat sebagian pihak lebih berkontribusi pada penyebab masalahnya, sehingga ada dimensi tanggung jawab, bukan cuma kebaikan hati.",hint:"Ada dimensi keadilan, bukan cuma kebaikan hati."},
{n:85,type:"mcq",micro:"Menyikapi negosiasi internasional yang alot",q:"Perundingan internasional tentang suatu isu global sering berjalan lambat & sulit mencapai kesepakatan penuh. Ini terjadi karena...",options:["semua negara jahat & tidak mau bekerja sama","tiap negara punya kepentingan, kondisi ekonomi, & prioritas berbeda yang perlu diselaraskan, sehingga kompromi butuh waktu & negosiasi yang cermat","perundingan seperti ini tidak ada gunanya"],answer:1,explain:"Menyelaraskan kepentingan hampir 200 negara adalah proses yang rumit; kesabaran & diplomasi dibutuhkan untuk mencapai kemajuan.",hint:"Banyak kepentingan berbeda perlu diselaraskan."},
{n:86,type:"order",micro:"Dari kepedulian remaja ke dampak nyata",q:"Urutkan bagaimana kepedulian seorang remaja pada isu global bisa berkembang menjadi dampak nyata:",items:["Belajar mendalam tentang satu isu dari sumber tepercaya","Mulai aksi kecil & konsisten di lingkungan terdekat (sekolah, komunitas)","Mengajak & menginspirasi orang lain untuk ikut peduli & bertindak","Aksi kolektif ini bergabung dengan usaha serupa di tempat lain, menjadi bagian gerakan yang lebih besar"],answer:[0,1,2,3],explain:"Banyak gerakan besar dunia dimulai dari pola ini: belajar, bertindak lokal, mengajak, lalu menyatu dengan usaha yang lebih luas.",hint:"Belajar dulu, menyatu dengan gerakan besar di akhir."},
{n:87,type:"mcq",micro:"Menggabungkan dengan keterampilan lain",q:"Memahami masalah global bekerja paling baik bila digabung dengan...",options:["tidak perlu keterampilan lain","hanya menghafal daftar masalah","berpikir kritis (menilai data & klaim), empati (memahami dampak pada manusia nyata), & kerja sama (bertindak bersama orang lain)"],answer:2,explain:"Literasi tentang isu global adalah simpul yang terhubung dengan berpikir kritis, empati, & kolaborasi.",hint:"Gabung dengan berpikir kritis, empati, & kerja sama."},
{n:88,type:"open",micro:"Rancang rencana aksi jangka menengah",q:"Rancang rencana sederhana selama satu semester untuk kamu & beberapa teman mengangkat kepedulian pada satu isu global di sekolah, mulai dari belajar sampai aksi nyata.",sample:"Bulan 1: membentuk kelompok kecil & mempelajari isu sampah plastik dari sumber tepercaya, termasuk data sekolah sendiri (berapa banyak sampah plastik dihasilkan). Bulan 2: merancang & mengajukan program 'Jumat Tanpa Plastik Sekali Pakai' ke pihak sekolah, membuat poster edukasi. Bulan 3: menjalankan program, mencatat perubahan jumlah sampah, & membagikan hasilnya lewat presentasi kelas atau mading, mengajak kelas lain ikut serta.",explain:"Rencana bertahap (belajar → rancang → jalankan → bagikan) membuat kepedulian jangka panjang lebih mungkin berhasil.",hint:"Rencana per bulan: belajar, rancang, jalankan, bagikan."},
{n:89,type:"mcq",micro:"Menilai kemajuan diri sendiri",q:"Tanda bahwa pemahamanmu tentang masalah global berkembang matang:",options:["kamu semakin bisa memegang kejujuran tentang tantangan besar sekaligus tetap mencari & melakukan tindakan nyata yang bisa kamu ambil","kamu semakin yakin satu solusi tunggal akan menyelesaikan segalanya","kamu merasa dunia tidak ada harapan & berhenti peduli"],answer:0,explain:"Kematangan terlihat dari kemampuan menyeimbangkan kejujuran & harapan yang aktif, bukan pesimisme atau optimisme naif.",hint:"Jujur pada tantangan + tetap bertindak."},
{n:90,type:"tf",micro:"Tujuan akhir",q:"Benar atau Salah: Tujuan mempelajari masalah bersama umat manusia adalah membangun pemahaman yang jujur & kepedulian yang aktif, bukan untuk membuat kita merasa bersalah atau putus asa.",answer:true,explain:"Pembelajaran yang sehat mengarah pada tindakan bermakna, bukan rasa bersalah yang melumpuhkan.",hint:"Menuju tindakan, bukan rasa bersalah/putus asa."},
{n:91,type:"mcq",micro:"Menyikapi perbedaan prioritas antarnegara",q:"Sebuah negara yang sedang berjuang memenuhi kebutuhan dasar rakyatnya mungkin belum bisa memprioritaskan isu global tertentu (mis. isu yang lebih jangka panjang) sebesar negara yang lebih makmur. Sikap yang memahami:",options:["menghakimi negara itu sebagai tidak peduli","memahami bahwa prioritas berbeda karena kondisi & kebutuhan mendesak yang berbeda, & dukungan internasional bisa membantu menyelaraskan prioritas jangka pendek & panjang","memaksa semua negara memprioritaskan hal yang sama persis"],answer:1,explain:"Empati terhadap konteks & kebutuhan berbeda tiap negara penting sebelum menghakimi prioritas mereka.",hint:"Kondisi berbeda, prioritas bisa berbeda; dukungan membantu menyelaraskan."},
{n:92,type:"mcq",micro:"Kekuatan cerita & data bersama",q:"Kampanye kesadaran isu global yang paling efektif biasanya menggabungkan...",options:["hanya cerita tanpa data sama sekali","hanya angka & statistik tanpa cerita manusia","data yang akurat DENGAN cerita manusia yang membuatnya terasa nyata & bisa dipahami secara emosional"],answer:2,explain:"Data memberi kredibilitas & skala; cerita manusia memberi makna & empati. Keduanya saling melengkapi.",hint:"Gabungkan data akurat + cerita manusia."},
{n:93,type:"open",micro:"Refleksi menyeluruh",q:"Setelah mempelajari topik ini, tuliskan 2-3 kalimat tentang bagaimana kamu ingin menyikapi masalah global mulai sekarang — pikiran, sikap, atau kebiasaan apa yang ingin kamu bawa.",sample:"Aku ingin membaca berita tentang isu global dengan lebih kritis, mencari sumber tepercaya & tidak langsung percaya klaim yang berlebihan. Aku juga ingin memilih satu atau dua isu yang benar-benar kupedulikan & melakukan tindakan kecil yang konsisten, daripada merasa kewalahan oleh semua masalah dunia sekaligus. Aku percaya usaha kecilku, digabung dengan usaha banyak orang lain, bisa berarti.",explain:"Refleksi yang mengarah pada sikap & kebiasaan nyata membuat pembelajaran tentang isu global lebih berdampak dalam hidup sehari-hari.",hint:"2-3 kalimat niat nyata, dengan katamu sendiri."},
{n:94,type:"mcq",micro:"Menyikapi ketidaksepakatan yang sehat",q:"Dua ahli yang sama-sama kredibel punya pandangan berbeda tentang cara terbaik menangani suatu isu global. Sikap yang matang:",options:["pahami bahwa perbedaan pandangan ahli tentang SOLUSI TERBAIK itu wajar & bisa didiskusikan dengan data, berbeda dari meragukan FAKTA DASAR yang sudah disepakati luas","menolak mendengarkan keduanya","menganggap salah satu pasti berbohong"],answer:0,explain:"Membedakan perdebatan tentang solusi (wajar & sehat) dari penyangkalan terhadap fakta dasar yang sudah didukung luas oleh bukti adalah keterampilan berpikir yang penting.",hint:"Beda pendapat soal solusi ≠ menyangkal fakta dasar."},
{n:95,type:"tf",micro:"Warisan untuk masa depan",q:"Benar atau Salah: Bagaimana generasi sekarang menangani masalah bersama umat manusia (lingkungan, kesehatan, pendidikan) akan memengaruhi kondisi yang diwariskan pada generasi berikutnya.",answer:true,explain:"Keputusan & tindakan hari ini membentuk kondisi dunia yang akan dijalani oleh anak & cucu generasi mendatang.",hint:"Tindakan hari ini membentuk warisan masa depan."},
{n:96,type:"mcq",micro:"Menghindari dua sikap ekstrem",q:"Dua sikap yang sama-sama kurang membantu saat menghadapi isu global:",options:["tidak ada sikap yang bermasalah","putus asa total (menganggap tidak ada gunanya berusaha) & optimisme naif (menganggap semua akan baik-baik saja tanpa usaha apa pun)","hanya sikap pertama yang bermasalah"],answer:1,explain:"Sikap yang sehat berada di antara keduanya: harapan yang realistis & disertai tindakan nyata.",hint:"Bukan putus asa, bukan pula optimisme tanpa usaha."},
{n:97,type:"mcq",micro:"Menghubungkan lokal & global secara utuh",q:"Cara pandang yang matang tentang posisi diri dalam masalah global:",options:["hanya peduli lingkungan sendiri & mengabaikan dunia","hanya peduli hal besar & mengabaikan lingkungan sendiri","merawat & bertindak di lingkungan terdekat, sambil memahami bagaimana tindakan itu terhubung dengan usaha global yang lebih besar"],answer:2,explain:"'Berpikir global, bertindak lokal' menyatukan kepedulian luas dengan tindakan nyata yang bisa dijalankan.",hint:"Rawat yang dekat, pahami hubungannya dengan yang besar."},
{n:98,type:"order",micro:"Menanggapi berita menakutkan tentang isu global",q:"Kamu membaca berita yang sangat menakutkan tentang sebuah isu global. Urutkan responsmu yang sehat:",items:["Cek sumbernya & cari apakah beberapa sumber tepercaya melaporkan hal yang sama secara akurat","Pisahkan fakta inti dari bagian yang mungkin dilebih-lebihkan untuk menarik perhatian","Cari juga informasi tentang usaha/kemajuan yang sedang dilakukan terkait isu itu","Putuskan satu langkah kecil yang bisa kamu ambil, alih-alih hanya merasa cemas"],answer:[0,1,2,3],explain:"Cek sumber → pisahkan fakta dari sensasi → cari kemajuan yang ada → ambil langkah kecil.",hint:"Cek sumber dulu, ambil langkah kecil di akhir."},
{n:99,type:"open",micro:"Definisi pribadi",q:"Dengan kata-katamu sendiri, tuliskan (2-3 kalimat) apa artinya bagimu menjadi bagian dari generasi yang ikut menghadapi masalah bersama umat manusia.",sample:"Bagiku, itu berarti aku tidak menutup mata pada masalah besar dunia hanya karena aku masih pelajar & merasa kecil. Aku ingin terus belajar dengan kritis, memilih isu yang kupedulikan, & melakukan bagianku — sekecil apa pun — sambil percaya bahwa banyak orang seperti aku di seluruh dunia yang melakukan hal serupa bisa membuat perbedaan nyata.",explain:"Merumuskan makna pribadi membantu topik yang besar & abstrak ini terasa dekat & dapat dijalani.",hint:"2-3 kalimat, sungguh dengan katamu sendiri."},
{n:100,type:"mcq",micro:"Ringkasan Tantangan",q:"Inti memahami & menyikapi masalah bersama umat manusia yang matang:",options:["mengenali tantangan global secara jujur & berdasar bukti, memahami kompleksitas & keadilannya, tetap melihat kemajuan yang telah dicapai, & mengambil peran nyata sekecil apa pun sebagai bagian dari usaha bersama dunia","menganggap masalah global bukan urusan pelajar","hanya menyerah pada besarnya masalah dunia"],answer:0,explain:"Warga dunia yang matang menghadapi masalah bersama dengan kejujuran, pemahaman yang berimbang, & kesediaan bertindak — sekecil apa pun, sebagai bagian dari usaha yang jauh lebih besar.",hint:"Jujur & berbasis bukti + kemajuan + peran nyata."},
];
